fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // We will have exactly 2*n - 1 elements in the result
    let mut res = Vec::with_capacity(2 * n - 1);

    // For all but the last element, push the element and then the delimiter
    for &x in &numbers[..n - 1] {
        res.push(x);
        res.push(delim);
    }
    // Finally push the last element (no trailing delimiter)
    res.push(numbers[n - 1]);

    res
}

